@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--bg:#090914;--cyan:#50f6ec;--pink:#ff4d9d;--yellow:#f9ed75;--muted:#8a8ca7;--panel:rgba(17,18,37,.82)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:#f5f4ff;font-family:Manrope,system-ui,sans-serif;touch-action:none}body{display:grid;place-items:center}#game-shell{position:relative;width:min(100vw,177.78vh);height:min(100vh,56.25vw);min-height:320px;overflow:hidden;background:radial-gradient(ellipse at 50% 48%,#17182d 0%,#0b0b19 57%,#080811 100%);isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 30%,rgba(5,5,14,.22) 75%,rgba(5,5,14,.74) 130%);z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:74px;padding:0 4.1%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(198,200,255,.09);background:linear-gradient(180deg,rgba(8,9,20,.78),rgba(8,9,20,.22));pointer-events:none}.brand{display:grid;grid-template-columns:37px auto;grid-template-rows:22px 14px;column-gap:10px;align-items:center;color:#fff;text-decoration:none;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:19px;letter-spacing:1.6px;line-height:1}.brand-mark{grid-row:1/3;width:37px;height:37px;border:1px solid rgba(81,246,236,.58);color:var(--cyan);display:grid;place-items:center;font-size:22px;clip-path:polygon(25% 0,75% 0,100% 50%,75% 100%,25% 100%,0 50%);background:rgba(80,246,236,.08);text-shadow:0 0 15px var(--cyan)}.brand small{font:8px 'DM Mono',monospace;letter-spacing:2.4px;color:#7e829c}.slash{color:var(--cyan)}.run-stats{display:flex;gap:14px;align-items:center;font:11px 'DM Mono',monospace;letter-spacing:1px;color:#e8e7f8}.run-stats i{height:13px;width:1px;background:#3a3b54}.live-dot{height:6px;width:6px;border-radius:50%;background:var(--pink);box-shadow:0 0 12px var(--pink);animation:pulse 1.4s infinite}.icon-button{width:37px;height:37px;border:1px solid rgba(198,200,255,.17);background:rgba(19,20,40,.55);border-radius:50%;color:#e8e7ff;font-size:15px;cursor:pointer;pointer-events:auto}.icon-button:hover{border-color:var(--cyan);color:var(--cyan)}.hud{position:absolute;z-index:2;top:94px;left:4.1%;right:4.1%;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.player-card{display:flex;gap:11px;width:222px;padding:10px;background:rgba(13,14,30,.7);border:1px solid rgba(184,187,255,.12);clip-path:polygon(0 0,calc(100% - 12px) 0,100% 12px,100% 100%,0 100%);backdrop-filter:blur(8px)}.portrait{position:relative;width:42px;height:48px;display:grid;place-items:center;background:linear-gradient(145deg,#173e51,#14152d 70%);border:1px solid rgba(80,246,236,.36);color:var(--cyan);font-size:25px;text-shadow:0 0 14px var(--cyan)}.portrait b{position:absolute;right:3px;bottom:2px;font:8px 'DM Mono';color:#f9ed75}.player-info{flex:1;padding-top:1px}.row{display:flex;justify-content:space-between;align-items:center;font:9px 'DM Mono';color:#a7aac2;letter-spacing:.5px}.row b{font:700 10px 'DM Mono';color:#f4f3ff}.bar{height:4px;background:rgba(227,230,255,.12);margin:5px 0 7px;overflow:hidden}.bar span{display:block;width:100%;height:100%;transition:width .22s ease}.bar.hp span{background:linear-gradient(90deg,#ff4c9d,#ff967c);box-shadow:0 0 9px #ff4d9d}.xp-row{font-size:8px;color:#7c809b}.xp-row b{color:var(--cyan);font-size:8px}.xp-row span:first-child{letter-spacing:1px}.bar.xp{height:3px;margin:4px 0 0}.bar.xp span{background:linear-gradient(90deg,#4df5e7,#72a2ff);box-shadow:0 0 8px #50f6ec}.right-hud{display:flex;gap:10px;align-items:stretch}.kill-counter,.mod-chip{height:53px;padding:9px 12px;background:rgba(13,14,30,.7);border:1px solid rgba(184,187,255,.12);backdrop-filter:blur(8px)}.kill-counter{min-width:70px;text-align:right;font:17px 'DM Mono';color:#fff}.kill-counter .skull{float:left;color:var(--pink);font-size:17px;text-shadow:0 0 12px var(--pink)}.kill-counter small,.mod-chip small{display:block;font:7px 'DM Mono';letter-spacing:1.5px;color:#83869f;margin-top:1px}.mod-chip{display:flex;gap:9px;align-items:center;min-width:132px}.mod-chip>span{font-size:22px;color:var(--yellow);text-shadow:0 0 12px #f6db4a}.mod-chip b{font:10px 'DM Mono';letter-spacing:.4px}.boss-bar{position:absolute;z-index:2;top:161px;left:50%;transform:translateX(-50%);width:min(360px,70%);display:flex;gap:10px;align-items:center;color:var(--pink)}.boss-bar>span{font-size:22px}.boss-bar>div{flex:1}.boss-bar b{font:10px 'DM Mono';letter-spacing:1px;color:#ffe4f2}.boss-bar .bar{margin:5px 0 0;height:5px}.boss-bar .bar span{background:var(--pink)}.boss-bar small{font:8px 'DM Mono';letter-spacing:1px}.bottom-hud{position:absolute;z-index:2;bottom:29px;left:4.1%;right:4.1%;display:flex;justify-content:space-between;align-items:flex-end;pointer-events:none}.objective,.weapon-pill{display:flex;align-items:center;gap:10px;padding:10px 13px;background:rgba(13,14,30,.7);border:1px solid rgba(184,187,255,.12);backdrop-filter:blur(8px)}.objective-icon{font-size:24px;color:var(--cyan);text-shadow:0 0 13px var(--cyan)}.objective small,.weapon-pill small{display:block;font:7px 'DM Mono';letter-spacing:1.4px;color:#81849d}.objective b,.weapon-pill b{display:block;font:10px 'DM Mono';letter-spacing:.3px;margin-top:4px}.weapon-pill{min-width:196px}.weapon-pill>span:first-child{font-size:20px;color:var(--yellow);text-shadow:0 0 12px #f9ed75}.weapon-pill em{font-style:normal;color:var(--cyan);font-size:8px}.weapon-state{font:7px 'DM Mono';color:var(--cyan);border:1px solid rgba(80,246,236,.32);padding:4px 5px;margin-left:auto}.stick-zone,.dash-button{display:none}.overlay{position:absolute;z-index:6;inset:0;display:grid;place-items:center;background:rgba(6,7,17,.62);backdrop-filter:blur(5px);animation:fadein .24s ease}.overlay.hidden,.boss-bar.hidden{display:none}.overlay-card,.pause-panel,.upgrade-panel{width:min(450px,90%);padding:38px 42px 28px;background:linear-gradient(145deg,rgba(19,21,43,.97),rgba(11,12,27,.98));border:1px solid rgba(137,151,255,.25);box-shadow:0 20px 100px rgba(0,0,0,.45),0 0 60px rgba(74,114,255,.08);position:relative;clip-path:polygon(0 0,calc(100% - 24px) 0,100% 24px,100% 100%,0 100%)}.overlay-card:before,.pause-panel:before,.upgrade-panel:before{content:'';position:absolute;top:0;left:0;width:90px;height:2px;background:var(--cyan);box-shadow:0 0 16px var(--cyan)}.eyebrow{display:flex;align-items:center;gap:8px;color:#9da1bd;font:8px 'DM Mono';letter-spacing:1.6px}.eyebrow>span{height:6px;width:6px;border-radius:50%;background:var(--cyan);box-shadow:0 0 10px var(--cyan)}h1,h2{margin:14px 0 10px;font:800 66px/.82 'Barlow Condensed',Impact,sans-serif;letter-spacing:1px}h1 span,h2 span{color:var(--cyan);text-shadow:0 0 25px rgba(80,246,236,.28)}.intro{max-width:330px;margin:17px 0 23px;color:#a6a8c0;font-size:11px;line-height:1.7}.feature-row{display:flex;gap:15px;padding:14px 0 17px;border-top:1px solid rgba(187,190,255,.11);border-bottom:1px solid rgba(187,190,255,.11)}.feature-row div{display:flex;align-items:center;gap:5px;color:#9296b2}.feature-row span{color:var(--pink);font-size:14px}.feature-row b{font:7px 'DM Mono';letter-spacing:.35px}.feature-row div:nth-child(2) span{color:var(--yellow)}.feature-row div:nth-child(3) span{color:var(--cyan)}.primary-button{display:flex;align-items:center;justify-content:space-between;width:100%;margin:19px 0 11px;padding:14px 17px;border:0;background:var(--cyan);color:#07141a;font:800 13px 'Barlow Condensed';letter-spacing:2px;cursor:pointer;box-shadow:0 0 26px rgba(80,246,236,.21);transition:transform .15s,box-shadow .15s}.primary-button:hover{transform:translateY(-2px);box-shadow:0 0 35px rgba(80,246,236,.4)}.primary-button b{font-size:18px}.controls-hint{display:flex;align-items:center;justify-content:center;gap:8px;font:7px 'DM Mono';letter-spacing:.6px;color:#9b9db6}.controls-hint i{font-style:normal;color:#4f526b}.mod-line{display:flex;gap:9px;align-items:center;margin-top:23px;padding-top:13px;border-top:1px solid rgba(187,190,255,.1);font:8px 'DM Mono';color:#b4b6ca}.mod-icon{font-size:20px;color:var(--yellow)}.mod-line b{color:#f5f3ff}.mod-line small{display:block;margin-top:3px;color:#7d819c}.mod-on{margin-left:auto;color:var(--cyan);font:7px 'DM Mono';white-space:nowrap}.pause-panel,.upgrade-panel{width:min(410px,90%);padding:36px 38px 30px}.pause-panel h2,.upgrade-panel h2{font-size:52px;margin:18px 0}.pause-panel h2 span,.upgrade-panel h2 span{color:var(--pink);text-shadow:0 0 22px rgba(255,77,157,.25)}.pause-panel p,.upgrade-panel>p{font-size:10px;color:#989bb5;margin:0 0 24px}.text-button{display:block;margin:13px auto 0;background:none;border:0;color:#a5a8bf;font:8px 'DM Mono';letter-spacing:1.2px;cursor:pointer}.text-button:hover{color:var(--cyan)}.text-button span{color:var(--cyan);padding-left:6px}.upgrade-panel{width:min(620px,92%)}.upgrade-panel h2{font-size:44px}.upgrade-panel h2 span{color:var(--cyan)}.upgrade-panel>p{font:8px 'DM Mono';letter-spacing:1px}.upgrade-options{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.upgrade-card{position:relative;min-height:142px;padding:15px 13px;text-align:left;background:rgba(34,37,67,.45);border:1px solid rgba(154,159,230,.2);color:white;cursor:pointer;transition:all .16s}.upgrade-card:hover{transform:translateY(-4px);border-color:var(--cyan);background:rgba(45,69,87,.55);box-shadow:0 0 25px rgba(80,246,236,.12)}.upgrade-card .upgrade-icon{font-size:24px;color:var(--cyan);display:block;margin-bottom:12px}.upgrade-card:nth-child(2) .upgrade-icon{color:var(--pink)}.upgrade-card:nth-child(3) .upgrade-icon{color:var(--yellow)}.upgrade-card b{display:block;font:700 11px 'DM Mono';letter-spacing:.2px}.upgrade-card p{font-size:9px;line-height:1.55;color:#a4a7c0;margin:7px 0 0}.upgrade-card small{position:absolute;right:9px;top:9px;color:#8589a7;font:7px 'DM Mono'}.toast{position:absolute;z-index:4;top:22%;left:50%;transform:translate(-50%,-10px);padding:10px 18px;background:rgba(12,18,34,.86);border:1px solid rgba(80,246,236,.3);font:9px 'DM Mono';letter-spacing:1px;color:var(--cyan);opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.danger>span{background:var(--pink);box-shadow:0 0 10px var(--pink)}
@keyframes pulse{50%{opacity:.35;box-shadow:0 0 3px var(--pink)}}@keyframes fadein{from{opacity:0}to{opacity:1}}
@media(max-width:700px){#game-shell{width:100vw;height:100dvh;min-height:0}.topbar{height:60px;padding:0 16px}.brand{grid-template-columns:30px auto;grid-template-rows:18px 11px;column-gap:7px;font-size:15px}.brand-mark{width:30px;height:30px;font-size:18px}.brand small{font-size:6px;letter-spacing:1.7px}.run-stats{gap:8px;font-size:9px}.icon-button{width:32px;height:32px}.hud{top:73px;left:13px;right:13px}.player-card{width:177px;padding:7px;gap:8px}.portrait{width:34px;height:40px;font-size:20px}.row{font-size:7px}.row b{font-size:8px}.xp-row b{font-size:7px}.mod-chip{display:none}.kill-counter{height:43px;min-width:56px;padding:6px 8px;font-size:14px}.kill-counter small{font-size:6px}.bottom-hud{bottom:20px;left:14px;right:14px}.objective{display:none}.weapon-pill{min-width:157px;padding:8px 9px;gap:7px}.weapon-pill b{font-size:8px}.weapon-pill small{font-size:6px}.weapon-state{font-size:6px}.stick-zone{display:block;position:absolute;z-index:3;left:15px;bottom:57px;width:130px;height:130px;touch-action:none}.stick-base{position:absolute;inset:10px;border-radius:50%;border:1px solid rgba(80,246,236,.22);background:rgba(17,24,44,.25);box-shadow:inset 0 0 30px rgba(80,246,236,.04)}.stick-knob{position:absolute;left:50%;top:50%;width:48px;height:48px;margin:-24px;border-radius:50%;background:rgba(80,246,236,.18);border:1px solid rgba(80,246,236,.55);box-shadow:0 0 20px rgba(80,246,236,.17);transform:translate(0,0)}.stick-zone>span{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font:7px 'DM Mono';letter-spacing:1px;color:rgba(207,227,236,.45);pointer-events:none}.dash-button{display:flex;position:absolute;z-index:3;right:24px;bottom:73px;width:65px;height:65px;border:1px solid rgba(255,77,157,.55);border-radius:50%;background:radial-gradient(circle,rgba(255,77,157,.22),rgba(35,15,37,.72));color:#ff77b2;flex-direction:column;align-items:center;justify-content:center;gap:1px;box-shadow:0 0 24px rgba(255,77,157,.12);touch-action:manipulation}.dash-button span{font-size:22px;line-height:21px;transform:rotate(-45deg)}.dash-button small{font:7px 'DM Mono';letter-spacing:1px}.dash-button i{position:absolute;inset:3px;border:1px solid rgba(255,255,255,.08);border-radius:50%;pointer-events:none}.overlay-card{padding:27px 24px 21px;width:min(430px,91%)}h1{font-size:56px;margin-top:13px}.intro{font-size:10px;margin:14px 0 17px}.feature-row{gap:8px;padding:11px 0 13px}.feature-row b{font-size:6px}.mod-line{margin-top:17px}.upgrade-panel{padding:28px 20px 22px}.upgrade-panel h2{font-size:38px}.upgrade-options{gap:6px}.upgrade-card{padding:12px 9px;min-height:136px}.upgrade-card b{font-size:9px}.upgrade-card p{font-size:8px}.upgrade-card .upgrade-icon{font-size:20px;margin-bottom:9px}.boss-bar{top:131px}.pause-panel{padding:30px 26px}.pause-panel h2{font-size:47px}}
@media(max-height:600px) and (min-width:701px){.topbar{height:58px}.hud{top:72px}.bottom-hud{bottom:16px}.overlay-card{padding-top:25px;padding-bottom:19px}.intro{margin:12px 0 16px}.mod-line{margin-top:15px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d', { alpha: false });
  const $ = (id) => document.getElementById(id);
  const ui = { clock: $('clock'), wave: $('wave-label'), hp: $('hp-bar'), hpText: $('hp-text'), xp: $('xp-bar'), xpText: $('xp-label'), level: $('level-label'), kills: $('kill-count'), mod: $('mod-label'), overlay: $('overlay'), levelup: $('levelup'), options: $('upgrade-options'), pause: $('pause-overlay'), gameover: $('gameover'), summary: $('run-summary'), toast: $('toast'), boss: $('boss-bar'), bossHealth: $('boss-health') };
  const TAU = Math.PI * 2;
  let W = 0, H = 0, dpr = 1, last = 0, raf = 0, state = 'menu', elapsed = 0, spawnTimer = 0, shotTimer = 0, shake = 0, screenFlash = 0, toastTimer = 0;
  let player, enemies = [], bullets = [], enemyBullets = [], particles = [], gems = [], pickups = [], floaters = [], hazards = [], decor = [], keys = new Set(), mouse = { x: 0, y: 0 }, pointer = null, joystick = { x: 0, y: 0 }, touchMode = false;
  let upgrades = { damage: 1, speed: 1, radius: 1, multishot: 1, magnet: 1, armor: 0, luck: 0, regen: 0, crit: 0, chain: 0 }, wave = 1, boss = null, modCycle = 0, score = 0;
  const mods = ['OVERDRIVE', 'PHASE SHARDS', 'VOID MAGNET', 'CRITICAL MASS'];
  const rand = (a, b) => a + Math.random() * (b - a);
  const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
  const dist2 = (a, b) => (a.x - b.x) ** 2 + (a.y - b.y) ** 2;
  function resize() {
    const r = canvas.getBoundingClientRect(); W = r.width; H = r.height; dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.floor(W * dpr); canvas.height = Math.floor(H * dpr); ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    decor = []; for (let i = 0; i < 90; i++) decor.push({ x: Math.random() * W, y: Math.random() * H, s: rand(.4, 1.6), a: rand(.12, .5), p: rand(0, TAU) });
    if (player) { player.x = clamp(player.x, 25, W - 25); player.y = clamp(player.y, 90, H - 35); }
  }
  window.addEventListener('resize', resize); resize();
  const mobile = () => matchMedia('(max-width: 700px)').matches || navigator.maxTouchPoints > 0;
  function reset() {
    elapsed = 0; spawnTimer = .4; shotTimer = 0; shake = 0; screenFlash = 0; wave = 1; boss = null; score = 0;
    enemies = []; bullets = []; enemyBullets = []; particles = []; gems = []; pickups = []; floaters = []; hazards = [];
    upgrades = { damage: 1, speed: 1, radius: 1, multishot: 1, magnet: 1, armor: 0, luck: 0, regen: 0, crit: 0, chain: 0 };
    player = { x: W / 2, y: H / 2, r: 12, hp: 100, maxHp: 100, xp: 0, next: 30, level: 1, speed: 188, invuln: 0, dash: 0, dashCooldown: 0, facing: 0, regenTick: 0, kills: 0, shootBonus: 0 };
    ui.mod.textContent = mods[0]; ui.boss.classList.add('hidden'); updateHud();
  }
  function start() { reset(); ui.overlay.classList.add('hidden'); ui.pause.classList.add('hidden'); ui.gameover.classList.add('hidden'); state = 'playing'; last = performance.now(); cancelAnimationFrame(raf); raf = requestAnimationFrame(loop); showToast('SIGNAL LINK ESTABLISHED'); }
  function showToast(text) { ui.toast.textContent = text; ui.toast.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => ui.toast.classList.remove('show'), 1500); }
  function formatTime(s) { const mm = Math.floor(s / 60).toString().padStart(2, '0'); const ss = Math.floor(s % 60).toString().padStart(2, '0'); return `${mm}:${ss}`; }
  function updateHud() {
    if (!player) return;
    ui.hp.style.width = `${100 * player.hp / player.maxHp}%`; ui.hpText.textContent = `${Math.ceil(player.hp)} / ${player.maxHp}`;
    ui.xp.style.width = `${100 * player.xp / player.next}%`; ui.xpText.textContent = `${player.xp} / ${player.next}`;
    ui.level.textContent = `LV ${String(player.level).padStart(2, '0')}`; ui.kills.textContent = String(player.kills).padStart(3, '0');
  }
  function pos(e) { const r = canvas.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; }
  window.addEventListener('keydown', e => {
    if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key)) e.preventDefault();
    keys.add(e.key.toLowerCase()); if (e.key.toLowerCase() === 'escape' || e.key.toLowerCase() === 'p') togglePause(); if ((e.key === ' ' || e.key.toLowerCase() === 'shift') && state === 'playing') dash();
  });
  window.addEventListener('keyup', e => keys.delete(e.key.toLowerCase()));
  canvas.addEventListener('pointermove', e => { const p = pos(e); mouse = p; if (e.pointerType === 'mouse') pointer = p; });
  canvas.addEventListener('pointerdown', e => { if (e.pointerType === 'mouse') pointer = pos(e); });
  canvas.addEventListener('pointerleave', () => { pointer = null; });
  const stick = $('stick-zone'), base = $('stick-base'), knob = $('stick-knob');
  function updateStick(e) { const r = base.getBoundingClientRect(), cx = r.left + r.width / 2, cy = r.top + r.height / 2; let dx = e.clientX - cx, dy = e.clientY - cy; const max = r.width * .35, len = Math.hypot(dx, dy); if (len > max) { dx *= max / len; dy *= max / len; } joystick.x = dx / max; joystick.y = dy / max; knob.style.transform = `translate(${dx}px,${dy}px)`; }
  stick.addEventListener('pointerdown', e => { e.preventDefault(); touchMode = true; stick.setPointerCapture(e.pointerId); updateStick(e); });
  stick.addEventListener('pointermove', e => { if (stick.hasPointerCapture(e.pointerId)) updateStick(e); });
  const clearStick = () => { joystick.x = joystick.y = 0; knob.style.transform = 'translate(0,0)'; };
  stick.addEventListener('pointerup', clearStick); stick.addEventListener('pointercancel', clearStick);
  $('dash-button').addEventListener('pointerdown', e => { e.preventDefault(); dash(); });
  function togglePause() { if (state === 'playing') { state = 'paused'; ui.pause.classList.remove('hidden'); } else if (state === 'paused') { state = 'playing'; ui.pause.classList.add('hidden'); last = performance.now(); raf = requestAnimationFrame(loop); } }
  $('pause-button').addEventListener('click', togglePause); $('resume-button').addEventListener('click', togglePause); $('start-button').addEventListener('click', start); $('retry-button').addEventListener('click', start); $('quit-button').addEventListener('click', () => { ui.pause.classList.add('hidden'); ui.overlay.classList.remove('hidden'); state = 'menu'; });
  $('skip-upgrade').addEventListener('click', () => { ui.levelup.classList.add('hidden'); state = 'playing'; last = performance.now(); raf = requestAnimationFrame(loop); });
  function dash() { if (!player || player.dashCooldown > 0 || state !== 'playing') return; player.dash = .18; player.dashCooldown = 2.2; player.invuln = .36; const d = moveVector(); let dx = d.x, dy = d.y; if (Math.hypot(dx, dy) < .1) { const near = nearestEnemy(); if (near) { dx = player.x - near.x; dy = player.y - near.y; } else dx = 1; } const n = Math.hypot(dx, dy) || 1; player.x += dx / n * 68; player.y += dy / n * 68; player.x = clamp(player.x, 20, W - 20); player.y = clamp(player.y, 82, H - 25); burst(player.x, player.y, '#50f6ec', 20, 200); shake = 5; }
  function moveVector() { let x = joystick.x, y = joystick.y; if (Math.abs(x) + Math.abs(y) < .08) { x = (keys.has('d') || keys.has('arrowright') ? 1 : 0) - (keys.has('a') || keys.has('arrowleft') ? 1 : 0); y = (keys.has('s') || keys.has('arrowdown') ? 1 : 0) - (keys.has('w') || keys.has('arrowup') ? 1 : 0); } const n = Math.hypot(x, y); return n > 1 ? { x: x / n, y: y / n } : { x, y }; }
  function nearestEnemy() { let target = null, best = Infinity; for (const e of enemies) { const d = dist2(e, player); if (d < best) { best = d; target = e; } } return target; }
  function spawnEnemy() {
